+    public static Matcher<Exports> exportsOf(String pkg) {
+        return new ExportsMatcher(pkg, Set.of());
+    }
+
+    public static Matcher<Exports> exportsOf(String pkg, Set<String> targets) {
+        return new ExportsMatcher(pkg, targets);
+    }
+
